import{_ as t,o as d,c as o,ag as r}from"./chunks/framework.Pp2klvcf.js";const m=JSON.parse('{"title":"UI 模式与样式兼容","description":"","frontmatter":{},"headers":[],"relativePath":"zh/polyrepo/ui-theme.md","filePath":"zh/polyrepo/ui-theme.md","lastUpdated":1788681727000}'),a={name:"zh/polyrepo/ui-theme.md"};function c(i,e,h,l,n,s){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ui-模式与样式兼容" tabindex="-1">UI 模式与样式兼容 <a class="header-anchor" href="#ui-模式与样式兼容" aria-label="Permalink to &quot;UI 模式与样式兼容&quot;">​</a></h1><h2 id="四类构建期适配" tabindex="-1">四类构建期适配 <a class="header-anchor" href="#四类构建期适配" aria-label="Permalink to &quot;四类构建期适配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>别名</th><th>责任</th></tr></thead><tbody><tr><td><code>@ui-setup</code></td><td>必要样式、全局组件、主题服务初始化</td></tr><tr><td><code>@ui-theme</code></td><td>框架 Theme/Config Provider</td></tr><tr><td><code>@login-adapter</code></td><td>用户名、密码输入和 submit 事件</td></tr><tr><td><code>@ui-showcase</code></td><td>当前框架组件示例</td></tr></tbody></table><p><code>all</code> 组合各展示组件，登录复用 Element Plus；不复制七套页面业务逻辑。Ant Design 使用 <code>ant-</code> 前缀，Arco 使用 <code>a-</code>，避免解析器冲突。</p><h2 id="样式约束" tabindex="-1">样式约束 <a class="header-anchor" href="#样式约束" aria-label="Permalink to &quot;样式约束&quot;">​</a></h2><p>应用颜色使用 <code>--fv-*</code>，页面类名使用 <code>fv-*</code> 或 scoped CSS。不要直接把 Arco 的 <code>--color-text-*</code> 当成所有页面的设计变量，也不要使用全局 <code>input { border: none }</code>、<code>a { color: black !important }</code> 覆盖第三方组件。</p><p>页面布局由应用控制：展示按钮使用可换行的 flex 容器；登录表单宽度由响应式面板决定；图表使用容器 ref 和 ResizeObserver；避免固定 550px 侧栏或重复 <code>100vh</code> 导致溢出。</p><table tabindex="0"><thead><tr><th>UI</th><th>深浅主题实现</th></tr></thead><tbody><tr><td>Ant Design Vue</td><td>ConfigProvider 的 theme algorithm</td></tr><tr><td>Naive UI</td><td>NConfigProvider 与 darkTheme</td></tr><tr><td>iDux</td><td>IxThemeProvider 的 presetTheme</td></tr><tr><td>Element Plus</td><td><code>.dark</code> 与 dark/css-vars.css</td></tr><tr><td>Arco</td><td>body 的 arco-theme 属性</td></tr><tr><td>TDesign</td><td>html 的 theme-mode 属性</td></tr><tr><td>DevUI</td><td>ThemeService.applyTheme</td></tr></tbody></table><p>同一 Pinia 状态驱动所有适配。DevUI 的内部 <code>d-icon</code> 需要显式注册；其组件 resolver 不能用于任意脚本标识符自动导入。</p><h2 id="新增框架" tabindex="-1">新增框架 <a class="header-anchor" href="#新增框架" aria-label="Permalink to &quot;新增框架&quot;">​</a></h2><p>更新 <code>config/ui.ts</code>、resolver 清单、四类适配文件、<code>.env.&lt;mode&gt;</code> 和 package scripts；将框架加入 CI 构建矩阵。新增组件要分别验证浅色、深色、窄屏、键盘输入和浏览器控制台。内置示例覆盖的是现有表单/按钮，不表示所有第三方弹层组合都已验证。</p>',11)])])}const u=t(a,[["render",c]]);export{m as __pageData,u as default};
